contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user) public {
        // The test contract deployed c, so wards(address(this)) == 1 at construction.
        bool senderIsWard = c.wards(address(this)) == 1;

        bool reverted;
        try c.rely(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 userWardAfter = c.wards(user);

        // Since the only initial ward is the deployer (this contract), an authorized
        // caller must succeed and make user a ward, while an unauthorized caller must
        // revert and leave wards[user] unchanged (zero in a fresh deployment).
        if (senderIsWard) {
            assert(!reverted && userWardAfter == 1);
        } else {
            assert(reverted && userWardAfter == 0);
        }
    }
}

