contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public {
        require(caller != address(0), "zero caller");

        uint256 callerWardBefore = c.wards(caller);

        bool reverted;
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(c.deny.selector, user));
        reverted = !ok;

        if (callerWardBefore != 1) {
            assert(reverted);
        } else {
            assert(!reverted && c.wards(user) == 0);
        }
    }
}

