        // value is a non-negative number of shares. Additionally, since a successful
        // call is the only observable way this contract reports shares, the call must
        // not silently complete with a value that is outside the range the investment
        // manager can mint. In particular, a successful deposit of assets > 0 must
        // return a consistent uint256 value that is itself reachable as the result of
        // the investment manager's processDeposit path, which is monotonic in the
        // sense that it cannot exceed the total share supply after the call.
        assert(
            !reverted
                ? shares <= c.totalSupply()
                : true
        );
    }

    receive() external payable {}
}

