contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 value) public {
        // Record the ward state of the caller before any state-changing calls.
        uint256 callerWardBefore = c.wards(caller);

        // The test contract is deployed by the test, but c was deployed in the same test transaction
        // so the deployer is the test contract.  The only ward is the deployer (this contract).
        // Calling mint from a non-ward address must revert because of the auth modifier.
        bool reverted;
        try c.mint(caller, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 callerWardAfter = c.wards(caller);

        // General rule: mint from a caller that is not currently a ward reverts and does not change the ward mapping.
        // Additionally, if the test contract itself is the only ward, mint(address(this), value) also reverts because
        // the share contract call inside will fail (share address is a parameter, but here we cannot supply it).
        // However, the only safe general statement we can make with the available parameters is that
        // an unauthorized call reverts and leaves the ward state unchanged.
        assert(reverted && callerWardBefore == callerWardAfter);
    }

    receive() external payable {}
}

