contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 what, address data, bool callerIsWard) public payable {
        // Arrange the caller's authorization status: the test contract is the initial ward,
        // so to act as a non-ward we first deny ourselves, and to act as a ward we rely ourselves.
        if (!callerIsWard) {
            // only the current ward (this contract) can call deny; c is fresh so wards(this)==1
            c.deny(address(this));
        } else {
            c.rely(address(this));
        }

        // Deciding call: file on c through the public entry point.
        bool reverted;
        try c.file(what, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule:
        // - Unauthorized callers ALWAYS revert (the before-call ward flag is 0).
        // - Authorized callers revert exactly when the selector/key is unrecognized,
        //   i.e. when `what` is anything other than the recognized "investmentManager" key.
        bool recognized = (what == bytes32("investmentManager"));
        if (!callerIsWard) {
            assert(reverted);
        } else {
            assert(!reverted == recognized);
        }
    }
}

